/* Types */
/**  Settings for people who want to look under the hood. */
export type Advanced = {
	/**  How much the log files record. */
	logLevel: LogLevel,
	/**  Turns on the web engine's developer tools (F12). */
	developerMode: boolean,
	/**  Use the title bar of Windows instead of the one Arden Code draws. */
	nativeTitleBar: boolean,
	/**
	 *  Let the graphics card draw the window. Turning it off works around graphics problems and
	 *  needs a restart.
	 */
	hardwareAcceleration: boolean,
};

/**  The agent programs Arden Code will work with. */
export type AgentCli = 
/**  The Claude Code program from Anthropic, `claude`. */
"claude" | 
/**  The Codex program, `codex`. */
"codex";

/**  Which agent answers in a session. Claude and Codex arrive with their drivers. */
export type AgentKind = 
/**  The built-in demonstration agent. */
"demo";

/**
 *  The error every command returns: a code, the translation key of its message, and details for
 *  the logs and for "Copy details".
 */
export type AppError = {
	code: ErrorCode,
	/**  The key in the UI's language file that says what happened, why, and what to do. */
	messageKey: string,
	/**  Technical detail that helps find the cause. Never shown as the message itself. */
	details: string | null,
};

/**  What the app knows about itself. */
export type AppInfo = {
	name: string,
	version: string,
	/**  The short id of the commit this build was made from, or `unknown`. */
	commit: string,
	/**  The date of that commit as `YYYY-MM-DD`, or `unknown`. */
	buildDate: string,
};

/**  How the app looks. */
export type Appearance = {
	/**  Light, dark, or follow Windows. */
	theme: Theme,
	/**  How large everything is, from 80 to 200 percent. */
	zoom: number,
	/**  Make the app larger or smaller with the Windows text size setting, on top of the zoom. */
	followTextSize: boolean,
	/**  The size of code text, from 11 to 20 pixels. */
	codeFontSize: number,
	/**  Join characters such as `=>` into one symbol in code. */
	codeLigatures: boolean,
	/**  Play fewer animations. */
	reduceMotion: ReduceMotion,
	/**  Show the bar along the bottom of the window. */
	showStatusBar: boolean,
};

/**  What a check found, for the person who asked for it. */
export type CheckResult = 
/**  This is the newest version. */
"upToDate" | 
/**  A new version is downloaded and waits for a restart. */
"ready" | 
/**  A check or a download is already going on. */
"busy" | 
/**  The check could not be done: no release exists yet, or the internet is not reachable. */
"unavailable" | 
/**  A release exists, but its signature is not valid, so it was not used. */
"rejected";

/**  What was found about one agent program. */
export type Detection = {
	cli: AgentCli,
	installed: boolean,
	/**  The file that would be started. */
	path: string | null,
	/**  Its version, when it could be read. */
	version: string | null,
	/**  Where to install it. */
	installUrl: string,
};

/**  One line of a log file, in the shape the log viewer shows. */
export type Entry = {
	/**  When it happened, as `2026-09-30T14:05:09.123Z`. */
	timestamp: string,
	/**  `error`, `warn`, `info`, `debug` or `trace`. */
	level: string,
	/**  Which part of the app wrote it: a Rust module, or `ui/<part>` for a message from the UI. */
	source: string,
	message: string,
	/**  The error code, when the line is about an error. */
	code: string | null,
};

/**
 *  Every error a user can see. The written form, `ARD-<AREA>-<NNN>`, is stable and appears both on
 *  the error screen and in the logs. Codes are listed in `docs/error-codes.md`, and a test keeps
 *  that page in sync with this enum. Never reuse or renumber a code.
 */
export type ErrorCode = 
/**  Something went wrong that nobody planned for. */
"ARD-APP-001" | 
/**  The UI hit an error it could not handle. */
"ARD-APP-002" | 
/**  Arden Code could not get ready to reset itself. */
"ARD-APP-003" | 
/**  A link was not opened: it is not allowed, or Windows could not open it. */
"ARD-APP-004" | 
/**  A notification could not be shown. */
"ARD-APP-005" | 
/**  A reset could not finish, so the settings were kept and the next start tries again. */
"ARD-APP-006" | 
/**  The settings could not be saved. */
"ARD-SET-001" | 
/**  The settings file was not valid, so the defaults are in use. */
"ARD-SET-002" | 
/**  A settings file could not be imported. */
"ARD-SET-003" | 
/**  The settings could not be exported. */
"ARD-SET-004" | 
/**  `settings.json` could not be opened. */
"ARD-SET-005" | 
/**  The logs folder could not be opened. */
"ARD-LOG-001" | 
/**  The diagnostics bundle could not be written. */
"ARD-LOG-002" | 
/**  A session or project does not exist any more. */
"ARD-AGT-001" | 
/**  A message was sent while the agent was still answering the last one. */
"ARD-AGT-002" | 
/**  The sessions could not be saved, so they last only until Arden Code closes. */
"ARD-AGT-003" | 
/**  The saved sessions could not be read, so Arden Code started without them. */
"ARD-AGT-004" | 
/**  A name given to a session is empty or too long. */
"ARD-AGT-006" | 
/**  Programs cannot be started and supervised on this computer. */
"ARD-PROC-001" | 
/**  The update could not be installed. */
"ARD-UPD-001" | 
/**  Windows' window menu could not be opened. */
"ARD-WIN-001" | 
/**  The web engine that draws the window stopped and was started again. */
"ARD-WIN-002";

/**  What happened to a file. */
export type FileChangeKind = "created" | "modified" | "deleted";

/**  How the app behaves in general. */
export type General = {
	/**  Restore the last session, or start fresh. */
	onStartup: OnStartup,
	/**  Look for a new version now and then, without asking. */
	checkForUpdates: boolean,
	/**  How dates and numbers are written. */
	regionalFormat: RegionalFormat,
};

/**  One part of an agent's reply. */
export type Item = 
/**  What the agent says, in Markdown. It grows while the reply streams. */
{ type: "text"; id: string; text: string } | 
/**  The agent's reasoning. It grows while the reply streams. */
{ type: "thinking"; id: string; text: string } | 
/**  The agent using a tool, such as reading a file or running a command. */
{ type: "toolCall"; id: string; 
/**  The tool's name, such as `read_file`. */
name: string; 
/**  What the tool was asked to do, in a line. */
input: string; status: ToolStatus; 
/**  What the tool answered, once it has. */
output: string | null } | 
/**  A file the agent created, changed or deleted. */
{ type: "fileChange"; id: string; 
/**  The file's path, relative to the project. */
path: string; change: FileChangeKind; added: number; removed: number } | 
/**  Something the agent reports as having gone wrong. */
{ type: "error"; id: string; message: string } | 
/**  A marker between the parts of a reply. */
{ type: "status"; id: string; kind: StatusKind };

/**  The shortcuts a person changed. A command that is not here has its default shortcuts. */
export type Keyboard = {
	/**
	 *  For each command that was changed, its shortcuts, written like `Ctrl+Shift+P`. An empty
	 *  list means the command has no shortcut.
	 */
	shortcuts: { [key in string]: string[] },
};

/**  How wide the side panels were left. */
export type Layout = {
	/**  The sidebar's width in pixels. */
	sidebarWidth: number,
	/**  The inspector's width in pixels. */
	inspectorWidth: number,
};

/**  How much the log files record. */
export type LogLevel = 
/**  Only what went wrong. */
"error" | 
/**  What went wrong, and what looks wrong. */
"warn" | 
/**  The above, and what the app does (the default). */
"info" | 
/**  Everything, for finding a bug. Files grow faster. */
"debug";

/**  Where the page's Maximize button is, in physical pixels from the top left of the page. */
export type MaximizeButtonArea = {
	x: number,
	y: number,
	width: number,
	height: number,
};

/**
 *  Sent to the UI when the Maximize button should look different: the page cannot see the pointer
 *  on it, because the overlay takes it.
 */
export type MaximizeButtonChanged = {
	look: MaximizeButtonLook,
};

/**  How the Maximize button should look while the pointer is on it or presses it. */
export type MaximizeButtonLook = "normal" | "hover" | "pressed";

/**  Whether Arden Code may show Windows notifications. */
export type Notifications = {
	/**  Show notifications, such as when an agent needs the person. With this off, nothing is shown. */
	desktop: boolean,
};

/**  What the app does when it starts. */
export type OnStartup = 
/**  Open the session that was open last time. */
"restore" | 
/**  Start with no session open. */
"fresh";

/**  A folder on disk where agents work. */
export type Project = {
	id: string,
	kind: ProjectKind,
	/**  The folder's name. */
	name: string,
	/**  The folder's full path. */
	path: string,
};

/**  What a project is. Only the Playground exists in the foundation. */
export type ProjectKind = 
/**  The folder the app makes for itself, for Demo agent sessions. */
"playground" | 
/**  A folder the person opened, for example with the `arden-code` command. */
"folder";

/**  A project and its sessions, the most recently used first. */
export type ProjectListing = {
	project: Project,
	sessions: SessionSummary[],
};

/**
 *  The pages of the project that the app can open in the browser. Each one is a fixed address, so
 *  nothing the UI is given can send the browser somewhere else.
 */
export type ProjectPage = 
/**  The release notes. */
"releases" | 
/**  The privacy statement. */
"privacy";

/**  Whether animations play. */
export type ReduceMotion = 
/**  Follow the Windows "Show animations" setting. */
"system" | 
/**  Always reduce motion. */
"on" | 
/**  Never reduce motion. */
"off";

/**  Which regional format dates and numbers are written in. */
export type RegionalFormat = 
/**  The format chosen in Windows, even when it differs from the language of the interface. */
"windows" | 
/**  English (US), whatever Windows says. */
"english";

/**  A session: the turns with one agent, in one project. */
export type Session = {
	id: string,
	projectId: string,
	agent: AgentKind,
	/**  The first message, shortened, or nothing until there is one. */
	title: string | null,
	/**  When the session was created, in UTC. */
	createdAt: string,
	/**  When a message was last sent in it, or when it was created if none was, in UTC. */
	updatedAt: string,
	/**  Whether it is pinned to the top of the sidebar (ADR 0036). */
	pinned: boolean,
	turns: Turn[],
};

/**  The sessions as the sidebar lists them. */
export type SessionList = {
	/**  The pinned sessions, whatever their project, in the order they were pinned. */
	pinned: SessionSummary[],
	/**
	 *  Every project, the Playground first and the others in the order they were opened, each with
	 *  its sessions that are not pinned.
	 */
	projects: ProjectListing[],
};

/**  Tells the page to show a session, such as the one made for a folder that was opened. */
export type SessionRequested = {
	sessionId: string,
};

/**  A session as the sidebar lists it. */
export type SessionSummary = {
	id: string,
	projectId: string,
	agent: AgentKind,
	title: string | null,
	createdAt: string,
	updatedAt: string,
	pinned: boolean,
};

